import { SheetPanels } from '../../slots/defs/sheetPanels';
import { twoDecimals } from '../rates/rates';
import { useSheetTotals, useTagDueTotals } from './claims';

// The sheet's claimed-total, due-total, overdue count and total, and settled-total and open-total (see useSheetTotals),
// and the due-total of each tag ever used on the sheet (see useTagDueTotals).
function ClaimedTotal({ sheet }: { sheet: string; user: string }) {
  const { claimed, due, overdue, settled, open } = useSheetTotals(sheet);
  const tags = useTagDueTotals(sheet);
  return (
    <>
      <p>
        Claimed total: <strong data-testid="rollup-claimed-total">{claimed}</strong>
      </p>
      <p>
        Due total: <strong data-testid="rollup-due-total">{twoDecimals(due)}</strong>
      </p>
      <p>
        Overdue: <strong data-testid="rollup-overdue-count">{overdue.count}</strong>, total{' '}
        <strong data-testid="rollup-overdue-total">{twoDecimals(overdue.cents)}</strong>
      </p>
      <p>
        Settled total: <strong data-testid="rollup-settled-total">{twoDecimals(settled)}</strong>, open total{' '}
        <strong data-testid="rollup-open-total">{twoDecimals(open)}</strong>
      </p>
      {tags.length > 0 && (
        <ul>
          {tags.map(({ tag, cents }) => (
            <li key={tag}>
              Tag {tag} due total: <strong data-testid={`tag-${tag}-due-total`}>{twoDecimals(cents)}</strong>
            </li>
          ))}
        </ul>
      )}
    </>
  );
}

export const contribution = SheetPanels.fill({ order: 20, Component: ClaimedTotal });
  const aged = { upTo30: 0n, upTo60: 0n, over60: 0n };
  const today = late.today;
  for (const c of counted(claims.filter((c) => c.person === person.id), [person])) {
    if (!isOpen(c)) continue;
    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
    const days =
      today === undefined ? 0 : Math.round((Date.parse(`${today}T00:00:00Z`) - Date.parse(`${c.date}T00:00:00Z`)) / 86_400_000);
    if (days <= 30) aged.upTo30 += due;
    else if (days <= 60) aged.upTo60 += due;
    else aged.over60 += due;
  }
  return aged;
}

/** Adds up the people's figures, leaving out the single highest and the single lowest when three or more people
 *  have a figure. */
export function trimmedSum(figures: bigint[]): bigint {
  const sum = figures.reduce((s, f) => s + f, 0n);
  if (figures.length < 3) return sum;
  const max = figures.reduce((m, f) => (f > m ? f : m));
  const min = figures.reduce((m, f) => (f < m ? f : m));
  return sum - max - min;
}

/** The sheet's totals: its claimed-total (everyone's counted claims added up), its due-total (everyone's due-total
 *  added up, skipping the people whose due-total is n/a, trimmed — see trimmedSum), and how many of the counted claims
 *  are overdue, with their total (each person's overdue-total, trimmed), and its settled-total and open-total. */
export function useSheetTotals(sheet: string): {
  claimed: string;
  due: bigint;
  overdue: { count: number; cents: bigint };
  settled: bigint;
  open: bigint;
} {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const today = useSheetToday(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);
  const cap = useCapCents(sheet);
  const due = trimmedSum(
    people
      .map((p) => personDueCents(all, rates, p, today, floor, late, cap))
      .filter((cents): cents is bigint => cents !== undefined),
  );
  const overdue = overdueCents(all, people, rates, late, floor);
  const perPerson = people.map((p) => overdueCents(all, [p], rates, late, floor).cents);
  // The settled-total and open-total: everyone's added up, not trimmed.
  const split = people.map((p) => splitDueCents(all, rates, p, floor, late));
  return {
    claimed: claimed(counted(all, people)),
    due,
    overdue: { count: overdue.count, cents: trimmedSum(perPerson) },
    settled: split.reduce((s, x) => s + x.settled, 0n),
    open: split.reduce((s, x) => s + x.open, 0n),
  };
}

/** Every tag ever carried by a claim on the sheet, sorted. */
export function sheetTags(claims: Claim[]): string[] {
  return [...new Set(claims.flatMap((c) => [...c.tagsEver, ...c.tags]))].sort();
}

/** The due-total of each tag ever used on the sheet (in hundredths): the dues of the claims that count (see
 *  {@link counted}) which carry it, a claim with two tags counting in both; a claim with no due adds nothing. */
export function useTagDueTotals(sheet: string): { tag: string; cents: bigint }[] {
  const { data: all = [] } = useClaims(sheet);
  const { data: people = [] } = usePeople(sheet);
  const { data: rates = [] } = useRates(sheet);
  const floor = useFloorCents(sheet);
  const late = useLate(sheet);
  const byId = new Map(people.map((p) => [p.id, p]));
  const totals = new Map(sheetTags(all).map((t) => [t, 0n]));
  for (const c of counted(all, people)) {
    const person = byId.get(c.person);
    if (person === undefined || c.tags.length === 0) continue;
    const due = claimDueCents(c, rateOf(rates, gradeOn(person, c.date), c.date), floor, late) ?? 0n;
    for (const t of c.tags) totals.set(t, (totals.get(t) ?? 0n) + due);
  }
  return [...totals].map(([tag, cents]) => ({ tag, cents }));
}

